package com.example.flashcardapp.main

import android.os.Bundle
import android.widget.TextView  // changes: update
import android.widget.ToggleButton
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.example.flashcardapp.R
import com.example.flashcardapp.data.Flashcard
import com.example.flashcardapp.data.FlashcardRepository
import com.example.flashcardapp.data.FlashcardRoomDatabase
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

// We'll define a small enum for readability:
private enum class SortField { QUESTION, ANSWER, NEXT_REVIEW, INTERVAL } // changes: update

class ListFlashcardsActivity : AppCompatActivity() {

    private lateinit var toggleReviewTime: ToggleButton
    private lateinit var flashcardRepository: FlashcardRepository
    private var flashcards: MutableList<Flashcard> = mutableListOf()
    private lateinit var flashcardAdapter: FlashcardAdapter

    // NEW: references to the clickable "column headers"
    private lateinit var tvHeaderQuestion: TextView  // changes: update
    private lateinit var tvHeaderAnswer: TextView    // changes: update
    private lateinit var tvHeaderTime: TextView      // changes: update
    private lateinit var tvHeaderInterval: TextView  // changes: update

    // Track our sort preference
    private var currentSortField: SortField = SortField.NEXT_REVIEW // changes: update
    private var ascending: Boolean = true // changes: update

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_list_flashcards)

        // Locate our new column-header views (make sure these IDs exist in the layout)
        tvHeaderQuestion = findViewById(R.id.tv_header_question) // changes: update
        tvHeaderAnswer   = findViewById(R.id.tv_header_answer)   // changes: update
        tvHeaderTime     = findViewById(R.id.tv_header_time)     // changes: update
        tvHeaderInterval = findViewById(R.id.tv_header_interval) // changes: update

        // Set click listeners that change sort field (and possibly flip ascending)
        tvHeaderQuestion.setOnClickListener { // changes: update
            if (currentSortField == SortField.QUESTION) {
                ascending = !ascending
            } else {
                currentSortField = SortField.QUESTION
                ascending = true
            }
            sortAndRefresh()
        }

        tvHeaderAnswer.setOnClickListener {
            if (currentSortField == SortField.ANSWER) {
                ascending = !ascending
            } else {
                currentSortField = SortField.ANSWER
                ascending = true
            }
            sortAndRefresh()
        }

        tvHeaderTime.setOnClickListener {
            if (currentSortField == SortField.NEXT_REVIEW) {
                ascending = !ascending
            } else {
                currentSortField = SortField.NEXT_REVIEW
                ascending = true
            }
            sortAndRefresh()
        }

        tvHeaderInterval.setOnClickListener {
            if (currentSortField == SortField.INTERVAL) {
                ascending = !ascending
            } else {
                currentSortField = SortField.INTERVAL
                ascending = true
            }
            sortAndRefresh()
        }

        toggleReviewTime = findViewById(R.id.toggle_review_time)
        flashcardRepository = FlashcardRepository(
            FlashcardRoomDatabase.getDatabase(applicationContext).flashcardDao()
        )

        flashcardAdapter = FlashcardAdapter(this, flashcards)
        val recyclerView = findViewById<RecyclerView>(R.id.recycler_view_flashcards)
        recyclerView.layoutManager = LinearLayoutManager(this)
        recyclerView.adapter = flashcardAdapter

        // Load initial data (future questions) but only where topics are selected
        loadFlashcards(true)

        toggleReviewTime.setOnCheckedChangeListener { _, isChecked ->
            if (isChecked) {
                // Show past questions with selected topics
                loadFlashcards(false)
            } else {
                // Show future questions with selected topics
                loadFlashcards(true)
            }
        }
    }

    private fun loadFlashcards(showFuture: Boolean) {
        lifecycleScope.launch(Dispatchers.IO) {
            val list: List<Flashcard> = if (showFuture) {
                flashcardRepository.getFutureFlashcardsForSelectedTopics(System.currentTimeMillis())
            } else {
                flashcardRepository.getPastFlashcardsForSelectedTopics(System.currentTimeMillis())
            }
            withContext(Dispatchers.Main) {
                flashcards.clear()
                flashcards.addAll(list)

                // After reloading, apply our current sort
                sortAndRefresh() // changes: update
            }
        }
    }

    // We'll define a helper function to sort the in-memory list
    private fun sortAndRefresh() { // changes: update
        when (currentSortField) {
            SortField.QUESTION -> {
                if (ascending) {
                    flashcards.sortBy { it.question }
                } else {
                    flashcards.sortByDescending { it.question }
                }
            }
            SortField.ANSWER -> {
                if (ascending) {
                    flashcards.sortBy { it.answer }
                } else {
                    flashcards.sortByDescending { it.answer }
                }
            }
            SortField.NEXT_REVIEW -> {
                if (ascending) {
                    flashcards.sortBy { it.nextReview }
                } else {
                    flashcards.sortByDescending { it.nextReview }
                }
            }
            SortField.INTERVAL -> {
                if (ascending) {
                    flashcards.sortBy { it.interval }
                } else {
                    flashcards.sortByDescending { it.interval }
                }
            }
        }
        flashcardAdapter.notifyDataSetChanged()
    }

    override fun onDestroy() {
        // No repository close needed
        super.onDestroy()
    }
}
